    66→        /// </summary>
    67→        /// <param name="header">BlockHeader to validate</param>
    68→        /// <param name="parent">BlockHeader which is the parent of <paramref name="header"/></param>
    69→        /// <param name="isUncle"><value>True</value> if uncle block, otherwise <value>False</value></param>
