    71→        public virtual bool Validate(BlockHeader header, BlockHeader? parent, bool isUncle = false)
    72→        {
    73→            return Validate(header, parent, isUncle, out _);
    74→        }
    75→
    76→        /// <summary>
    77→        /// Note that this does not validate seal which is the responsibility of <see cref="ISealValidator"/>>
    78→        /// </summary>
    79→        /// <param name="header">BlockHeader to validate</param>
    80→        /// <param name="parent">BlockHeader which is the parent of <paramref name="header"/></param>
    81→        /// <param name="isUncle"><value>True</value> if uncle block, otherwise <value>False</value></param>
    82→        /// <param name="error">Detailed error message if validation fails, otherwise <value>null</value>.</param>
    83→        /// <returns><value>True</value> if validation succeeds otherwise <value>false</value></returns>
    84→        public virtual bool Validate(BlockHeader header, BlockHeader? parent, bool isUncle, out string? error)
    85→        {
    86→            IReleaseSpec spec;
    87→            error = null;
    88→
    89→            // bool gasLimitAboveAbsoluteMinimum = header.GasLimit >= 125000; // described in the YellowPaper but not followed
    90→            return ValidateFieldLimit(header, ref error)
    91→                && ValidateHash(header, ref error)
    92→                && ValidateExtraData(header, parent, spec = _specProvider.GetSpec(header), isUncle, ref error)
    93→                && ValidateParent(header, parent, ref error)
    94→                && ValidateTotalDifficulty(parent!, header, ref error)
    95→                && ValidateSeal(header, parent, isUncle, ref error)
    96→                && ValidateGasUsed(header, ref error)
    97→                && ValidateGasLimitRange(header, parent, spec, ref error)
    98→                && ValidateTimestamp(header, parent, ref error)
    99→                && ValidateBlockNumber(header, parent, ref error)
   100→                && Validate1559(header, parent, spec, ref error)
   101→                && ValidateBlobGasFields(header, parent, spec, ref error)
   102→                && ValidateRequestsHash(header, spec, ref error);
   103→        }
   104→
   105→        protected virtual bool ValidateRequestsHash(BlockHeader header, IReleaseSpec spec, ref string? error)
   106→        {
   107→            if (spec.RequestsEnabled)
   108→            {
   109→                if (header.RequestsHash is null)
   110→                {
   111→                    if (_logger.IsWarn) _logger.Warn("RequestsHash field is not set.");
   112→                    error = BlockErrorMessages.MissingRequests;
   113→                    return false;
   114→                }
   115→            }
   116→            else
   117→            {
   118→                if (header.RequestsHash is not null)
   119→                {
   120→                    if (_logger.IsWarn) _logger.Warn("RequestsHash field should not have value.");
   121→                    error = BlockErrorMessages.RequestsNotEnabled;
   122→                    return false;
   123→                }
   124→            }
   125→            return true;
   126→        }
   127→
   128→        protected virtual bool Validate1559(BlockHeader header, BlockHeader parent, IReleaseSpec spec, ref string? error)
   129→        {
   130→            if (spec.IsEip1559Enabled)
   131→            {
   132→                UInt256? expectedBaseFee = BaseFeeCalculator.Calculate(parent, spec);
   133→
   134→                if (expectedBaseFee != header.BaseFeePerGas)
   135→                {
   136→                    if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.ToString(BlockHeader.Format.Short)}) incorrect base fee. Expected base fee: {expectedBaseFee}, Current base fee: {header.BaseFeePerGas} ");
   137→                    error = BlockErrorMessages.InvalidBaseFeePerGas(expectedBaseFee, header.BaseFeePerGas);
   138→                    return false;
   139→                }
   140→            }
   141→
   142→            return true;
   143→        }
   144→
   145→        protected virtual bool ValidateBlockNumber(BlockHeader header, BlockHeader parent, ref string? error)
   146→        {
   147→            if (header.Number != parent.Number + 1)
   148→            {
   149→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - block number is not parent + 1");
   150→                error = BlockErrorMessages.InvalidBlockNumber;
   151→                return false;
   152→            }
   153→
   154→            return true;
   155→        }
   156→
   157→        protected virtual bool ValidateGasUsed(BlockHeader header, ref string? error)
   158→        {
   159→            if (header.GasUsed > header.GasLimit)
   160→            {
   161→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - gas used above gas limit");
   162→                error = BlockErrorMessages.ExceededGasLimit;
   163→                return false;
   164→            }
   165→
   166→            return true;
   167→        }
   168→
   169→        protected virtual bool ValidateParent(BlockHeader header, BlockHeader? parent, ref string? error)
   170→        {
   171→            if (parent is null)
   172→            {
   173→                if (header.Number != 0)
   174→                {
   175→                    if (_logger.IsDebug) _logger.Debug($"Orphan block, could not find parent ({header.ParentHash}) of ({header.Hash})");
   176→                    error = BlockErrorMessages.InvalidAncestor;
   177→                    return false;
   178→                }
   179→
   180→                bool isGenesisValid = ValidateGenesis(header);
   181→                if (!isGenesisValid)
   182→                {
   183→                    if (_logger.IsWarn) _logger.Warn($"Invalid genesis block header ({header.Hash})");
   184→                    error = BlockErrorMessages.InvalidGenesisBlock;
   185→                    return false;
   186→                }
   187→            }
   188→            else if (parent.Hash != header.ParentHash)
   189→            {
   190→                error = BlockErrorMessages.MismatchedParent(header.Hash, header.ParentHash, parent.Hash);
   191→                return false;
   192→            }
   193→
   194→            return true;
   195→        }
   196→
   197→        protected virtual bool ValidateSeal(BlockHeader header, BlockHeader parent, bool isUncle, ref string? error)
   198→        {
   199→            bool result = _sealValidator.ValidateParams(parent, header, isUncle);
   200→
   201→            if (!result)
   202→            {
   203→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - seal parameters incorrect");
   204→                error = BlockErrorMessages.InvalidSealParameters;
   205→            }
   206→
   207→            return result;
   208→        }
   209→
   210→        protected virtual bool ValidateFieldLimit(BlockHeader blockHeader, ref string? error)
   211→        {
   212→            // Note, these are out of spec. Technically, there could be a block with field with very high value that is
   213→            // valid when using ulong, but wrapped to negative value when using long. However, switching to ulong
   214→            // at this point can cause other unexpected error. So we just won't support it for now.
   215→
   216→            error = blockHeader switch
   217→            {
   218→                { Number: < 0 } => BlockErrorMessages.NegativeBlockNumber,
   219→                { GasLimit: < 0 } => BlockErrorMessages.NegativeGasLimit,
   220→                { GasUsed: < 0 } => BlockErrorMessages.NegativeGasUsed,
   221→                _ => null
   222→            };
   223→
   224→            if (error is null) return true;
   225→
   226→            if (_logger.IsWarn)
   227→                _logger.Warn($"Invalid block header ({blockHeader.Hash}) - {blockHeader switch
   228→                {
   229→                    { Number: < 0 } => $"Block number is negative {blockHeader.Number}",
   230→                    { GasLimit: < 0 } => $"Block GasLimit is negative {blockHeader.GasLimit}",
   231→                    { GasUsed: < 0 } => $"Block GasUsed is negative {blockHeader.GasUsed}",
   232→                    _ => error
   233→                }}");
   234→
   235→            return false;
   236→
   237→        }
   238→
   239→        protected virtual bool ValidateExtraData(BlockHeader header, BlockHeader? parent, IReleaseSpec spec, bool isUncle, ref string? error)
   240→        {
   241→            bool extraDataValid = header.ExtraData.Length <= spec.MaximumExtraDataSize
   242→                                   && (isUncle
   243→                                       || _daoBlockNumber is null
   244→                                       || header.Number < _daoBlockNumber
   245→                                       || header.Number >= _daoBlockNumber + 10
   246→                                       || Bytes.AreEqual(header.ExtraData, DaoExtraData));
   247→            if (!extraDataValid)
   248→            {
   249→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - DAO extra data not valid. MaximumExtraDataSize {spec.MaximumExtraDataSize}, ExtraDataLength {header.ExtraData.Length}, DaoBlockNumber: {_daoBlockNumber}");
   250→                error = BlockErrorMessages.InvalidExtraData;
   251→            }
   252→
   253→            return extraDataValid;
   254→        }
   255→
   256→        protected virtual bool ValidateGasLimitRange(BlockHeader header, BlockHeader parent, IReleaseSpec spec, ref string? error)
   257→        {
   258→            long adjustedParentGasLimit = Eip1559GasLimitAdjuster.AdjustGasLimit(spec, parent.GasLimit, header.Number);
   259→            long maxGasLimitDifference = adjustedParentGasLimit / spec.GasLimitBoundDivisor;
   260→
   261→            long maxNextGasLimit = adjustedParentGasLimit + maxGasLimitDifference;
   262→            bool notToHighWithOverflow = long.MaxValue - maxGasLimitDifference < adjustedParentGasLimit;
   263→            // The edge case used in hive tests. If adjustedParentGasLimit + maxGasLimitDifference >=  long.MaxValue,
   264→            // we can check for long.MaxValue - maxGasLimitDifference < adjustedParentGasLimit to ensure that we are in range.
   265→            // In hive we have tests that using long.MaxValue in the genesis block
   266→            // Even if we add maxGasLimitDifference we don't get header.GasLimit higher than long.MaxValue
   267→            var gasLimitNotTooHigh = notToHighWithOverflow || header.GasLimit < maxNextGasLimit;
   268→
   269→            if (!gasLimitNotTooHigh)
   270→            {
   271→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - gas limit too high");
   272→                error = BlockErrorMessages.InvalidGasLimit;
   273→            }
   274→
   275→            bool gasLimitNotTooLow = header.GasLimit > adjustedParentGasLimit - maxGasLimitDifference &&
   276→                                     header.GasLimit >= spec.MinGasLimit;
   277→            if (!gasLimitNotTooLow)
   278→            {
   279→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - gas limit too low. " +
   280→                                                 $"Gas limit: {header.GasLimit}, " +
   281→                                                 $"Adjusted parent gas limit: {adjustedParentGasLimit}, " +
   282→                                                 $"Max gas limit difference: {maxGasLimitDifference}, " +
   283→                                                 $"Spec min gas limit: {spec.MinGasLimit}");
   284→                error = BlockErrorMessages.InvalidGasLimit;
   285→            }
   286→
   287→            return gasLimitNotTooHigh && gasLimitNotTooLow;
   288→        }
   289→
   290→        protected virtual bool ValidateTimestamp(BlockHeader header, BlockHeader parent, ref string? error)
   291→        {
   292→            bool timestampMoreThanAtParent = header.Timestamp > parent.Timestamp;
   293→            if (!timestampMoreThanAtParent)
   294→            {
   295→                error = BlockErrorMessages.InvalidTimestamp;
   296→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - timestamp before parent");
   297→            }
   298→            return timestampMoreThanAtParent;
   299→        }
   300→
   301→        protected virtual bool ValidateTotalDifficulty(BlockHeader parent, BlockHeader header, ref string? error)
   302→        {
   303→            bool result = true;
   304→
   305→            if (header.TotalDifficulty is not null)
   306→            {
   307→                if (header.TotalDifficulty == 0)
   308→                {
   309→                    // Same as in BlockTree.SetTotalDifficulty
   310→                    if (!(_blockTree.Genesis!.Difficulty == 0 && _specProvider.TerminalTotalDifficulty == 0))
   311→                    {
   312→                        if (_logger.IsDebug) _logger.Debug($"Invalid block header ({header.Hash}) - zero total difficulty when genesis or ttd is not zero");
   313→                        result = false;
   314→                        error = BlockErrorMessages.InvalidTotalDifficulty;
   315→                    }
   316→                }
   317→                else if (parent.TotalDifficulty + header.Difficulty != header.TotalDifficulty)
   318→                {
   319→                    if (_logger.IsDebug) _logger.Debug($"Invalid block header ({header.Hash}) - incorrect total difficulty");
   320→                    result = false;
   321→                    error = BlockErrorMessages.InvalidTotalDifficulty;
   322→                }
   323→            }
   324→
   325→            return result;
   326→        }
   327→
   328→        private bool ValidateGenesis(BlockHeader header) =>
   329→            header.GasUsed < header.GasLimit &&
   330→            header.GasLimit > _specProvider.GenesisSpec.MinGasLimit &&
   331→            header.Timestamp > 0 &&
   332→            header.Number == 0 &&
   333→            header.Bloom is not null &&
   334→            header.ExtraData.Length <= _specProvider.GenesisSpec.MaximumExtraDataSize;
   335→
   336→        protected virtual bool ValidateBlobGasFields(BlockHeader header, BlockHeader parentHeader, IReleaseSpec spec, ref string? error)
   337→        {
   338→            if (spec.IsEip4844Enabled)
   339→            {
   340→                if (header.BlobGasUsed is null)
   341→                {
   342→                    if (_logger.IsWarn) _logger.Warn("BlobGasUsed field is not set.");
   343→                    error = BlockErrorMessages.MissingBlobGasUsed;
   344→                    return false;
   345→                }
   346→
   347→                if (header.ExcessBlobGas is null)
   348→                {
   349→                    if (_logger.IsWarn) _logger.Warn("ExcessBlobGas field is not set.");
   350→                    error = BlockErrorMessages.MissingExcessBlobGas;
   351→                    return false;
   352→                }
   353→
   354→                ulong? expectedExcessBlobGas = BlobGasCalculator.CalculateExcessBlobGas(parentHeader, spec);
   355→                if (header.ExcessBlobGas != expectedExcessBlobGas)
   356→                {
   357→                    if (_logger.IsWarn) _logger.Warn($"ExcessBlobGas field is incorrect: {header.ExcessBlobGas}, should be {expectedExcessBlobGas}.");
   358→                    error = BlockErrorMessages.IncorrectExcessBlobGas(expectedExcessBlobGas, header.ExcessBlobGas);
   359→                    return false;
   360→                }
   361→            }
   362→            else
   363→            {
   364→                if (header.BlobGasUsed is not null)
   365→                {
   366→                    if (_logger.IsWarn) _logger.Warn("BlobGasUsed field should not have value.");
   367→                    error = BlockErrorMessages.NotAllowedBlobGasUsed;
   368→                    return false;
   369→                }
   370→
   371→                if (header.ExcessBlobGas is not null)
   372→                {
   373→                    if (_logger.IsWarn) _logger.Warn("ExcessBlobGas field should not have value.");
   374→                    error = BlockErrorMessages.NotAllowedExcessBlobGas;
   375→                    return false;
   376→                }
   377→            }
   378→
   379→            return true;
   380→        }
   381→    }
   382→}
   383→

