   101→            {
   102→                _finalTotalDifficulty = _syncConfig.PivotTotalDifficultyParsed;
   103→            }
   104→            else
   105→            {
   106→                if (_chainSpec?.Genesis is null) return;
   107→
   108→                UInt256 genesisDifficulty = _chainSpec.Genesis.Difficulty;
   109→                if (genesisDifficulty >= TerminalTotalDifficulty) // networks with the merge in genesis
   110→                {
   111→                    _finalTotalDifficulty = genesisDifficulty;
   112→                }
   113→            }
   114→        }
   115→
   116→        private void CheckIfTerminalBlockReached(object? sender, BlockEventArgs e)
   117→        {
   118→            TryUpdateTerminalBlock(e.Block.Header);
   119→        }
   120→
   121→        private void LoadFinalizedBlockHash()
   122→        {
   123→            _finalizedBlockHash = LoadHashFromDb(MetadataDbKeys.FinalizedBlockHash) ?? Keccak.Zero;
   124→        }
   125→
   126→        public bool TryUpdateTerminalBlock(BlockHeader header)
   127→        {
   128→            if (_terminalBlockExplicitSpecified || TransitionFinished || !header.IsTerminalBlock(_specProvider))
   129→            {
   130→                return false;
   131→            }
   132→
   133→            _terminalBlockNumber = header.Number;
   134→            _terminalBlockHash = header.Hash;
   135→            _metadataDb.Set(MetadataDbKeys.TerminalPoWNumber, Rlp.Encode(_terminalBlockNumber.Value).Bytes);
   136→            _metadataDb.Set(MetadataDbKeys.TerminalPoWHash, Rlp.Encode(_terminalBlockHash).Bytes);
   137→            _firstPoSBlockNumber = header.Number + 1;
   138→            _specProvider.UpdateMergeTransitionInfo(_firstPoSBlockNumber.Value);
   139→
   140→            if (_hasEverReachedTerminalDifficulty == false)
   141→            {
   142→                TerminalBlockReached?.Invoke(this, EventArgs.Empty);
   143→                _hasEverReachedTerminalDifficulty = true;
   144→                if (_logger.IsInfo) _logger.Info($"Reached terminal block {header}");
   145→            }
   146→            else
   147→            {
   148→                if (_logger.IsInfo) _logger.Info($"Updated terminal block {header}");
   149→            }
   150→
   151→            return true;
   152→        }
   153→
   154→        public void ForkchoiceUpdated(BlockHeader newHeadHash, Hash256 finalizedHash)
   155→        {
   156→            if (finalizedHash != Keccak.Zero && _finalizedBlockHash == Keccak.Zero)
   157→            {
   158→                _blockTree.NewHeadBlock -= CheckIfTerminalBlockReached;
   159→            }
   160→
   161→            if (finalizedHash != Keccak.Zero)
   162→            {
   163→                if (_finalizedBlockHash == Keccak.Zero)
   164→                {
   165→                    _blockTree.NewHeadBlock -= CheckIfTerminalBlockReached;
   166→                }
   167→
   168→                _finalizedBlockHash = finalizedHash;
   169→            }
   170→        }
